UPDATE public.b2b_managed_products SET
 name = 'Profi-Schwenkgrill Ø 120 cm',
 model_name = 'Großer Schwenkgrill mit 120 cm Rost – für Vereinsfeste, Firmenfeiern & Catering',
 description = 'Profi-Schwenkgrill mit 120 cm Grillrost, Kurbelzug und Feuerschale – für große Gruppen. Ab 90 € pro Tag, in Krefeld dauerhaft im Bestand.',
 detailed_description = 'Der Profi-Schwenkgrill mit 120 cm Rostdurchmesser ist unser größter Holzkohlegrill zum Mieten – gebaut für Vereinsfeste, Schützenfeste, Firmenfeiern, Hochzeiten und Catering, wo viele Portionen gleichzeitig vom Rost müssen. Rund 1,1 m² Grillfläche bieten Platz für Bratwürste, Steaks, Spieße und Gemüse in einem Durchgang.

Der runde Rost hängt an Ketten in einem stabilen Stahlgestell und wird über eine Handkurbel mit Seilzug stufenlos in der Höhe verstellt. So regelst du die Hitze über den Abstand zur Glut, statt Kohle nachschieben zu müssen – vom scharfen Angrillen bis zum Warmhalten. Der Rost lässt sich seitlich ausschwenken, um Glut nachzulegen oder das Grillgut bequem abzunehmen. Befeuert wird die Feuerschale mit Holzkohle, Briketts oder Holz.

Das Gerät ist rund 2,20 m hoch und wird für den Transport liegend verladen – ein Transporter oder Anhänger ist erforderlich. Wer selbst kein passendes Fahrzeug hat, mietet bei uns optional direkt einen passenden Anhänger zum Ankoppeln mit dazu; alternativ liefern wir den Grill an (Lieferkosten-Tarif A). Am Hauptsitz Krefeld ist der Schwenkgrill dauerhaft im Bestand, für Bonn und Mülheim an der Ruhr disponieren wir ihn aus Krefeld.',
 price_per_day = 'ab 90 €',
