 image_alts = ARRAY['Profi-Schwenkgrill Ø 120 cm mieten – Edelstahl-Feuerschale mit rundem Grillrost am Kettenzug','Schwenkgrill mieten – Gestell mit Handkurbel und Kette zur stufenlosen Höhenverstellung des 120-cm-Rostes'],
